// NOTATION for the evidence table: arg/output are shown with C-style escapes for
// non-printable bytes (\t=0x09, \n=0x0A, \v=0x0B, \f=0x0C, \r=0x0D, \xNN otherwise).
// All other characters are literal bytes. Outputs are the byte-exact contents of
// physical line 10 (excluding its terminating '\n'), captured with `od -c`.

FUNCTION parameterize(s: byte string, sep: byte string = "-") -> byte string:
    // Pure, single-pass, context-free per-byte map. No state, no lookahead,
    // no collapsing, no trimming, no normalization, no transliteration.
    result = ""                       // empty byte string
    FOR i = 0 TO length(s) - 1:
        c = s[i]                      // one raw byte, 0x01..0xFF
        IF c IS IN 'a'..'z' (0x61..0x7A) OR c IS IN '0'..'9' (0x30..0x39):
            append byte c to result                 // kept verbatim
        ELSE IF c IS IN 'A'..'Z' (0x41..0x5A):
            append byte (c + 0x20) to result        // ASCII-lowercased
        ELSE IF c == ' ' (0x20):
            append sep to result                    // exactly one separator per space
        ELSE:
            /* emit nothing — the byte is DELETED */
        END IF
    END FOR
    RETURN result                     // returned as-is: NOT squeezed, NOT stripped

// Equivalent one-liner:  result = concat over bytes b of s of
//     ascii_tolower(b) if ascii_isalnum(b) else sep if b == 0x20 else ""

// CONFIRMED PROPERTIES (each backed by probes below):
//  P1. The separator is emitted for byte 0x20 ONLY. All other C `isspace` bytes
//      — 0x09 TAB, 0x0A LF, 0x0B VT, 0x0C FF, 0x0D CR — are DELETED, exactly like
//      punctuation. => The reconnaissance hypothesis "else if it is whitespace"
//      is REFUTED; the correct predicate is `c == ' '`.
//  P2. Runs of separators are NOT collapsed/squeezed. N consecutive spaces yield
//      exactly N separator characters (verified up to N = 10 and in fuzzing).
//      Non-collapsing also holds ACROSS the template boundary: W=" lead" gives
//      "the--lead-test" (the space ending "The " and the leading space of W each
//      produce their own '-').
//  P3. Non-space bytes deleted from between two spaces do not merge them:
//      W="-a-" -> "the-a-test" but W=" -a- " -> "the--a--test".
//  P4. ASCII digits 0x30..0x39 are KEPT. Underscore 0x5F is DELETED (this is the
//      main divergence from Rails, which keeps '_'). Hyphen 0x2D is DELETED too
//      (so an already-parameterized string is NOT idempotent under this function).
//  P5. All high bytes 0x80..0xFF are DELETED unconditionally. Therefore every
//      non-ASCII UTF-8 character vanishes completely (2-, 3- and 4-byte
//      sequences alike): "café"->"caf", "naïve"->"nave", "ÄÖÜ"->"", "中文"->"",
//      U+1F600 -> "", NBSP (C2 A0) -> "", "€5" -> "5".
//  P6. All control bytes 0x01..0x1F and 0x7F are DELETED.
//  P7. Behavior is LOCALE-INDEPENDENT: identical output under LC_ALL=C,
//      C.UTF-8, en_US.UTF-8, tr_TR.UTF-8, en_US.ISO-8859-1. So the alnum/lower
//      tests are ASCII-hardcoded (or setlocale is never called). In particular
//      'I' -> 'i' even under tr_TR, and Latin-1 byte 0xC9 is dropped under
//      ISO-8859-1.
//  P8. No length limit / no truncation: verified with |W| = 1000, 10000 and
//      100000; output length matched the model exactly (809 / 8009 / 80009).
//  P9. The empty string maps to the empty string: W="" -> "the--test", i.e.
//      parameterize("The  Test") = "the" + "-" + "" + "-" + "test".

// VALIDATION: an exhaustive single-byte scan of W = "q" <b> "z" for every
// b in 0x01..0xFF (255 probes) produced exactly the map above, and 4 randomized
// fuzz campaigns (~2400 probes: random bytes, punctuation-heavy alphabet,
// space-heavy alphabet, lengths 0..1000) reported 0 mismatches against this
// pseudocode.

// ============================================================================
// NOTATION USED IN THE EVIDENCE ROWS BELOW:
//   Bytes inside printable ASCII (0x20..0x7E) are shown literally.
//   Every other byte is shown as \xHH (uppercase hex). A literal backslash
//   would be shown as \\ (none occurs in the rows). An empty output field
//   means a zero-length string was printed (followed by the '\n' from endl).
//   Args shown with \xHH were passed via bash ANSI-C quoting, e.g. $'caf\xC3\xA9',
//   and every byte was re-verified with `od -An -tx1`.
// ============================================================================
//
// MODEL: all three functions are PURE, STATELESS, BYTE-ORIENTED, ASCII-ONLY
// case mappings over the raw bytes of the argument. There is NO UTF-8
// awareness, NO locale awareness, NO word/whitespace/delimiter awareness,
// NO trimming, and NO length change -- ever.
//
// Exactly 52 of the 255 passable byte values are ever touched:
// 0x41..0x5A (A-Z) by downcase, and 0x61..0x7A (a-z) by upcase.
// All 203 other passable bytes (0x01..0x40, 0x5B..0x60, 0x7B..0xFF) are
// copied through byte-for-byte, INCLUDING every byte 0x80..0xFF, which is
// why UTF-8 continuation/lead bytes survive untouched.

FUNCTION ascii_upper_byte(b : uint8) -> uint8:
    IF b >= 0x61 AND b <= 0x7A THEN          // 'a'..'z'
        RETURN (uint8)(b - 0x20)
    ELSE
        RETURN b                              // identity for ALL other bytes
    END IF

FUNCTION ascii_lower_byte(b : uint8) -> uint8:
    IF b >= 0x41 AND b <= 0x5A THEN          // 'A'..'Z'
        RETURN (uint8)(b + 0x20)
    ELSE
        RETURN b                              // identity for ALL other bytes
    END IF


// ---------------------------------------------------------------- line 11 ---
FUNCTION upcase(s : byte_string) -> byte_string:
    n   = length_in_bytes(s)                  // byte count, NOT character count
    out = new byte_string of exactly n bytes
    FOR i = 0 TO n - 1:
        out[i] = ascii_upper_byte(s[i])       // each byte independent; no context
    END FOR
    RETURN out                                // length(out) == length(s) always


// ---------------------------------------------------------------- line 12 ---
FUNCTION downcase(s : byte_string) -> byte_string:
    n   = length_in_bytes(s)
    out = new byte_string of exactly n bytes
    FOR i = 0 TO n - 1:
        out[i] = ascii_lower_byte(s[i])       // each byte independent; no context
    END FOR
    RETURN out                                // length(out) == length(s) always


// ---------------------------------------------------------------- line 13 ---
FUNCTION capitalize(s : byte_string) -> byte_string:
    n = length_in_bytes(s)
    IF n == 0 THEN
        RETURN ""                             // empty in -> empty out
    END IF
    out    = new byte_string of exactly n bytes
    out[0] = ascii_upper_byte(s[0])           // FIRST BYTE (index 0), not first
                                              // character, not first letter,
                                              // not first non-space
    FOR i = 1 TO n - 1:
        out[i] = ascii_lower_byte(s[i])       // EVERY remaining byte lowercased
    END FOR
    RETURN out

// Exactly equivalent formulation, also fully consistent with all observations:
//     capitalize(s) == upcase(substr(s, 0, 1)) CONCAT downcase(substr(s, 1))
// (Whether the binary literally composes them this way is UNOBSERVABLE.)


// ============================== INVARIANTS PROVEN ============================
// I1. LENGTH: length(upcase(s)) == length(downcase(s)) == length(capitalize(s))
//     == length(s), for every input probed (incl. all 65025 two-byte inputs and
//     4000-byte inputs). No byte is ever inserted, dropped, or expanded --
//     so no 'ß'->"SS", no 'ﬁ'->"FI", no Turkish 'i'->'İ' expansion.
// I2. CONTEXT-FREEDOM: for upcase/downcase the output byte at index i depends
//     ONLY on s[i]. For capitalize it depends only on s[i] and on whether
//     i == 0. Proven by the COMPLETE 2-byte space plus 3-byte alphabet sweep.
// I3. ONLY-LETTERS-MOVE: empirically derived single-byte mapping tables contain
//     exactly 26 non-identity entries each and nothing else:
//       upcase   : 61->41 62->42 ... 7A->5A   (26 entries, all a-z)
//       downcase : 41->61 42->62 ... 5A->7A   (26 entries, all A-Z)
//       capitalize (1-byte input, i.e. index 0 only): 61->41 ... 7A->5A
//     Every one of the other 229 passable bytes maps to itself.
// I4. IDEMPOTENT: f(f(s)) == f(s) for all three (0 failures / 300 random
//     8-byte strings each). Follows from I3 since the images are disjoint from
//     the domains.
// I5. NO TRIMMING / NO WORD LOGIC: leading and trailing spaces, tabs, CRs and
//     newlines are preserved verbatim; capitalize does NOT skip leading
//     whitespace ('  lead' -> '  lead') and does NOT re-capitalize after a
//     space, '_' or '-' ('A B' -> 'A b', 'MiXeD_CaSe-99' -> 'Mixed_case-99').
// I6. NO LOCALE: identical output bytes under LC_ALL/LANG/LC_CTYPE = C,
//     C.UTF-8, en_US.UTF-8, tr_TR.UTF-8, de_DE.UTF-8. In particular
//     upcase('i') == 'I' (0x69 -> 0x49) even under tr_TR.UTF-8 -- never
//     0xC4 0xB0 ('İ') -- and 0xC3 0xA9 ('é') / 0xC3 0x89 ('É') never change.
// I7. NO UTF-8 AWARENESS: a multibyte first character is NOT titlecased;
//     capitalize($'\xC3\xA9ABC') == $'\xC3\xA9abc' (lead byte 0xC3 is merely
//     run through ascii_upper_byte, which is the identity), NOT 'ÉABC'.

// Notation: strings are mutable byte arrays. All three functions are pure byte
// transforms; no multibyte/UTF-8 awareness, no locale awareness, no trimming,
// no whitespace collapsing, no empty-string special case.
// In the evidence rows below, non-printable / non-ASCII bytes are written \xNN;
// everything else is literal. Outputs are quoted with '...' to make leading and
// trailing spaces unambiguous.

FUNCTION ascii_toupper(b: byte) -> byte:
    IF 0x61 <= b <= 0x7A THEN RETURN b - 0x20 ELSE RETURN b       // 'a'..'z' only

FUNCTION ascii_tolower(b: byte) -> byte:
    IF 0x41 <= b <= 0x5A THEN RETURN b + 0x20 ELSE RETURN b       // 'A'..'Z' only

// NOTE: these are the C/"POSIX"-locale toupper/tolower tables. Verified byte-by-byte
// for all 255 passable byte values: NO byte outside 0x41-0x5A / 0x61-0x7A is ever
// remapped (0x80-0xFF, incl. Latin-1 0xC9/0xE9 and UTF-8 lead/continuation bytes,
// pass through untouched). Output byte length always equals input byte length.


// ---------------------------------------------------------------- humanize -----
// = "underscores to spaces, then uppercase the FIRST BYTE"
FUNCTION humanize(s: bytes) -> bytes:
    out = copy_of(s)
    FOR i FROM 0 TO length(out) - 1:                  // unconditional global pass
        IF out[i] == 0x5F ('_') THEN out[i] = 0x20 (' ')
    IF length(out) > 0 THEN
        out[0] = ascii_toupper(out[0])                 // FIRST BYTE, not first letter
    RETURN out

// What humanize does NOT do (all refuted by probe):
//   - does NOT lowercase or otherwise touch bytes 1..n-1  ('cAT_id' -> 'CAT id')
//   - does NOT apply underscore()/decamelize        ('FooBar_id' -> 'FooBar id')
//   - does NOT strip a trailing "_id"               (W='' -> input '_id' -> ' id')
//   - does NOT touch '-', '.', or any other byte    ('a-b_id' -> 'A-b id')
//   - does NOT collapse or trim runs of spaces      ('a__b_id' -> 'A  b id')
//   - does NOT skip leading non-letters to find a letter: if out[0] is a space,
//     digit or punctuation it is passed to toupper (a no-op) and NO later byte is
//     uppercased  ('_x_id' -> ' x id',  '-foo_id' -> '-foo id',  '1a_id' -> '1a id')
// The two steps are order-independent as observed, because toupper('_')=='_' and
// toupper(' ')==' ' (see UNOBSERVABLE).


// ---------------------------------------------------------------- titleize -----
// = "downcase everything, then uppercase every byte that starts a
//    SPACE(0x20)-delimited run"
FUNCTION titleize(s: bytes) -> bytes:
    out = copy_of(s)
    FOR i FROM 0 TO length(out) - 1:                  // pass 1: global downcase
        out[i] = ascii_tolower(out[i])
    FOR i FROM 0 TO length(out) - 1:                  // pass 2: word starts
        IF i == 0 OR out[i-1] == 0x20 (' ') THEN
            out[i] = ascii_toupper(out[i])
    RETURN out

// Equivalent formulation (indistinguishable on every input tested):
//     tokens = split(s, on exactly one 0x20, keeping empty tokens)
//     for each token t: t = ascii_toupper(t[0]) + ascii_tolower(t[1..])
//     return join(tokens, 0x20)
//
// Word-boundary set is EXACTLY {0x20}. Established by brute force: for every byte
// b in 0x01..0xFF the input "Aa"+b+"Bb" was fed to titleize; ONLY b == 0x20
// produced 'Aa Bb' (uppercased 'B'). Non-boundaries explicitly include
// TAB 0x09, LF 0x0A, VT 0x0B, FF 0x0C, CR 0x0D, 0x01, 0x7F, NBSP-byte 0xA0,
// '_' 0x5F, '-' 0x2D, '.' 0x2E, '+' 0x2B, '/' 0x2F, all digits, all high bytes.
// Index 0 always counts as a word start.
// Consequences: a boundary byte that is not in 'a'..'z' is left as-is and does NOT
// "carry over" the capitalization to the next byte ('1abc' -> '1abc',
// '+a +b' -> '+a +b', '1a 2b' -> '1a 2b'). Leading/trailing/repeated spaces are
// preserved verbatim ('  lead' -> '  Lead', 'trail  ' -> 'Trail  ',
// 'foo  bar baz' -> 'Foo  Bar Baz'). No underscore()/humanize() is applied first
// ('foo_bar' -> 'Foo_bar', NOT 'Foo Bar'), and no camel-case splitting occurs
// ('FooBar' -> 'Foobar').


// --------------------------------------------------------------- dasherize -----
// = "every '_' becomes '-'; nothing else changes"
FUNCTION dasherize(s: bytes) -> bytes:
    out = copy_of(s)
    FOR i FROM 0 TO length(out) - 1:
        IF out[i] == 0x5F ('_') THEN out[i] = 0x2D ('-')
    RETURN out

// Case is fully preserved ('ABC_DEF' -> 'ABC-DEF', 'FooBar' -> 'FooBar').
// Every run of k underscores becomes k dashes, with no collapsing
// ('a__________b' -> 'a----------b'). Verified over all 255 byte values that no
// byte other than 0x5F is ever altered. dasherize('') == ''.
